DO $$ BEGIN CREATE TYPE "ContentFactoryJobPurpose" AS ENUM ('PLAN_MANIFEST','AUTHOR_GRAMMAR','AUTHOR_EXERCISES','VALIDATE','REVIEW','BUILD_FIXTURES','PUBLISH'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE "ContentFactoryJobState" AS ENUM ('QUEUED','CLAIMED','GENERATING','GENERATED','VALIDATING','IN_REVIEW','READY_FOR_APPROVAL','APPROVED','PUBLISHING','SUCCEEDED','CHANGES_REQUESTED','RETRY_WAIT','QUARANTINED','REJECTED','CANCELLED','FAILED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS "content_factory_runs" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"policy_version" TEXT NOT NULL DEFAULT 'content-factory-v1',"status" TEXT NOT NULL DEFAULT 'DRAFT ONLY',"manifest_code" TEXT,"manifest_hash" TEXT,"max_requests" INTEGER NOT NULL DEFAULT 100,"max_input_tokens" INTEGER NOT NULL DEFAULT 500000,"max_output_tokens" INTEGER NOT NULL DEFAULT 200000,"max_estimated_cost" DOUBLE PRECISION NOT NULL DEFAULT 10,"used_requests" INTEGER NOT NULL DEFAULT 0,"used_input_tokens" INTEGER NOT NULL DEFAULT 0,"used_output_tokens" INTEGER NOT NULL DEFAULT 0,"used_cost" DOUBLE PRECISION NOT NULL DEFAULT 0,"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "content_factory_jobs" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"run_id" UUID NOT NULL REFERENCES "content_factory_runs"("id") ON DELETE CASCADE,"purpose" "ContentFactoryJobPurpose" NOT NULL,"target_code" TEXT NOT NULL,"target_version" INTEGER NOT NULL DEFAULT 1,"state" "ContentFactoryJobState" NOT NULL DEFAULT 'QUEUED',"attempt" INTEGER NOT NULL DEFAULT 1,"idempotency_key" TEXT NOT NULL UNIQUE,"input_hash" TEXT NOT NULL,"output_hash" TEXT,"policy_versions_json" JSONB NOT NULL,"budget_json" JSONB NOT NULL,"worker_id" TEXT,"lease_expires_at" TIMESTAMPTZ,"normalized_error_code" TEXT,"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "content_factory_jobs_run_id_state_idx" ON "content_factory_jobs"("run_id","state"); CREATE INDEX IF NOT EXISTS "content_factory_jobs_state_lease_expires_at_idx" ON "content_factory_jobs"("state","lease_expires_at");
CREATE TABLE IF NOT EXISTS "content_factory_artifacts" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"run_id" UUID NOT NULL REFERENCES "content_factory_runs"("id") ON DELETE CASCADE,"job_id" UUID REFERENCES "content_factory_jobs"("id") ON DELETE SET NULL,"artifact_path" TEXT NOT NULL,"artifact_type" TEXT NOT NULL,"content_hash" TEXT NOT NULL,"storage_uri" TEXT NOT NULL,"metadata_json" JSONB NOT NULL DEFAULT '{}',"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "content_factory_artifacts_run_id_artifact_type_idx" ON "content_factory_artifacts"("run_id","artifact_type"); CREATE INDEX IF NOT EXISTS "content_factory_artifacts_content_hash_idx" ON "content_factory_artifacts"("content_hash");
CREATE TABLE IF NOT EXISTS "content_factory_approvals" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"run_id" UUID NOT NULL REFERENCES "content_factory_runs"("id") ON DELETE CASCADE,"approved_by" TEXT NOT NULL,"scope_hash" TEXT NOT NULL,"approval_hash" TEXT NOT NULL,"rationale" TEXT NOT NULL,"request_hash" TEXT NOT NULL DEFAULT '',"decision_source" TEXT NOT NULL DEFAULT 'OWNER_CLI',"approved_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE "content_factory_approvals" ADD COLUMN IF NOT EXISTS "request_hash" TEXT NOT NULL DEFAULT ''; ALTER TABLE "content_factory_approvals" ADD COLUMN IF NOT EXISTS "decision_source" TEXT NOT NULL DEFAULT 'OWNER_CLI';
CREATE UNIQUE INDEX IF NOT EXISTS "content_factory_approvals_run_id_scope_hash_key" ON "content_factory_approvals"("run_id","scope_hash"); CREATE INDEX IF NOT EXISTS "content_factory_approvals_run_id_approved_at_idx" ON "content_factory_approvals"("run_id","approved_at" DESC);
CREATE TABLE "content_validation_runs" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"run_id" UUID NOT NULL REFERENCES "content_factory_runs"("id") ON DELETE CASCADE,"job_id" UUID NOT NULL REFERENCES "content_factory_jobs"("id") ON DELETE CASCADE,"artifact_hash" TEXT NOT NULL,"validator_version" TEXT NOT NULL,"passed" BOOLEAN NOT NULL,"report_json" JSONB NOT NULL,"report_hash" TEXT NOT NULL,"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("job_id","artifact_hash","validator_version"));
CREATE INDEX "content_validation_runs_run_id_created_at_idx" ON "content_validation_runs"("run_id","created_at" DESC);
CREATE TABLE "content_review_runs" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"run_id" UUID NOT NULL REFERENCES "content_factory_runs"("id") ON DELETE CASCADE,"job_id" UUID NOT NULL REFERENCES "content_factory_jobs"("id") ON DELETE CASCADE,"artifact_hash" TEXT NOT NULL,"reviewer_provider" TEXT NOT NULL,"reviewer_model" TEXT NOT NULL,"prompt_version" TEXT NOT NULL,"decision" TEXT NOT NULL,"quality_score" DECIMAL(5,2) NOT NULL,"report_json" JSONB NOT NULL,"report_hash" TEXT NOT NULL,"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("job_id","artifact_hash","prompt_version"));
CREATE INDEX "content_review_runs_run_id_decision_created_at_idx" ON "content_review_runs"("run_id","decision","created_at" DESC);
CREATE TABLE "content_publications" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"run_id" UUID NOT NULL REFERENCES "content_factory_runs"("id") ON DELETE RESTRICT,"approval_id" UUID NOT NULL REFERENCES "content_factory_approvals"("id") ON DELETE RESTRICT,"batch_hash" TEXT NOT NULL UNIQUE,"status" TEXT NOT NULL,"release_id" UUID,"result_json" JSONB NOT NULL,"published_at" TIMESTAMPTZ,"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "content_publications_run_id_created_at_idx" ON "content_publications"("run_id","created_at" DESC); CREATE INDEX "content_publications_approval_id_idx" ON "content_publications"("approval_id");
